import os
import sys
import json
import csv
from datetime import date, timedelta
from decimal import Decimal
from collections import defaultdict

def convert_date(s: str) -> str:
    """Convert a date string to YYYY-MM-DD.
    Handles Excel serial numbers (days since 1899-12-30) and ISO dates.
    """
    s = s.strip()
    if not s:
        return None
    # Try ISO format YYYY-MM-DD
    try:
        d = date.fromisoformat(s)
        return d.isoformat()
    except Exception:
        pass
    # Try Excel serial number (days since 1899-12-30)
    try:
        serial = int(s)
        d = date(1899, 12, 30) + timedelta(days=serial)
        return d.isoformat()
    except Exception:
        pass
    # Try float conversion (e.g., "46157.0")
    try:
        serial = int(float(s))
        d = date(1899, 12, 30) + timedelta(days=serial)
        return d.isoformat()
    except Exception:
        pass
    # If all else fails, return the original string
    return s

def convert_amount(s: str) -> str:
    """Convert an amount string to a normalized decimal string.
    Removes commas and currency symbols, then normalizes trailing zeros.
    """
    s = s.strip()
    if not s:
        return None
    # Remove common currency symbols and thousands separators
    s_clean = s.replace(',', '').replace('$', '').strip()
    try:
        d = Decimal(s_clean)
        # Normalize removes trailing zeros (e.g., 104000.00 -> 104000)
        return str(d.normalize())
    except Exception:
        return s

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

