    rule_fact_field = {
        "lca.wage_105": {
            "offered wage": "WAGE_RATE_OF_PAY_FROM",
            "prevailing wage": "PREVAILING_WAGE"
        },
        "lca.three_years": {
            "begin date": "BEGIN_DATE",
            "end date": "END_DATE"
        }
    }

    # Document name (file name without extension)
    doc_name = "lca_disclosure"
    csv_file = os.path.join(packet_dir, doc_name + ".csv")

    # Read CSV and group by CASE_NUMBER
    case_data = defaultdict(lambda: defaultdict(list))
    with open(csv_file, 'r', newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case = row.get('CASE_NUMBER')
            if not case:
                continue
            for rule_id, fact_map in rule_fact_field.items():
                for fact_name, field in fact_map.items():
                    val = row.get(field) or ''
